import{_ as s,o as i,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/erz-berechtigte.png",b=JSON.parse('{"title":"Erziehungsberechtigte und Telefonnummern erfassen","description":"","frontmatter":{"title":"Erziehungsberechtigte und Telefonnummern erfassen","source_pageid":380,"source_revision":4690},"headers":[],"relativePath":"schild3/schueler/erz-berechtigte-telefonnummern-schueler.md","filePath":"schild3/schueler/erz-berechtigte-telefonnummern-schueler.md"}'),l={name:"schild3/schueler/erz-berechtigte-telefonnummern-schueler.md"};function d(u,r,g,h,c,m){return i(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="erziehungsberechtigte-und-telefonnummern-erfassen" tabindex="-1">Erziehungsberechtigte und Telefonnummern erfassen <a class="header-anchor" href="#erziehungsberechtigte-und-telefonnummern-erfassen" aria-label="Permalink to &quot;Erziehungsberechtigte und Telefonnummern erfassen&quot;">​</a></h1><p>Pflegen Sie Erziehungsberechtigte, Kontaktdaten und das Merkmal Erhält Anschreiben. Dieses Merkmal beeinflusst auch die Auswahl bei Serienbriefen.</p><p><a href="/bilder/schueler/erz-berechtigte.png"><img src="'+o+'" alt="Erziehungsberechtigte und deren Kontaktdaten." loading="lazy"></a></p><p><em>Erziehungsberechtigte und deren Kontaktdaten.</em></p><p>Auf der Registerkarte <em>Schüler</em>➜ <strong>Erz.-Berechtigte / Telefonnummern</strong> werden die Erziehungsberechtigten, deren Detaildaten und die Telefonnummern der Ansprechpartner erfasst.</p><h2 id="erziehungsberechtigte" tabindex="-1">Erziehungsberechtigte <a class="header-anchor" href="#erziehungsberechtigte" aria-label="Permalink to &quot;Erziehungsberechtigte&quot;">​</a></h2><p>Die Auflistung zeigt die <strong>Art</strong>, also das Verhältnis zum Kind, wie etwa <em>Eltern</em>, <em>Mutter</em>, <em>Vater</em>, <em>Jugendamt</em> usw.</p><p>Weiterhin den <strong>Namen</strong> der Erziehungsberechtigten, die <strong>Adresse</strong> und das Merkmal <strong>erhält Anschreiben</strong> für diese Person(en).</p><p><strong>Erhält Anschreiben</strong> steuert die Auswahl für Serienbriefe im Reporting beziehungsweise beim Export in externe Textverarbeitungsprogramme. Die Auswahl dokumentiert keine Sorge- oder Auskunftsberechtigung; prüfen Sie diese unabhängig davon anhand der vorliegenden Angaben.</p>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Hier ist zu beachten, dass jeder Eintrag zu "),e("em",null,"Art"),n(" zwei Personen enthalten kann. In der Regel werden hier also Mutter und Vater erfasst. Sollte nur eine Person erfasst sein, beachten Sie bitte, diese als die "),e("em",null,"1. Person"),n(" eingetragen wird, da ansonsten Adressbereiche in Reports falsch formatiert sein können.")])],-1),t('<h2 id="detaildaten" tabindex="-1">Detaildaten <a class="header-anchor" href="#detaildaten" aria-label="Permalink to &quot;Detaildaten&quot;">​</a></h2><p>Das Feld <strong>Art</strong> wird von den Daten oben übernommen.</p><p>Unter einer <strong>Art</strong> können Sie bis zu zwei Personen mit <strong>Anrede</strong>, <strong>Titel</strong>, <strong>Name</strong>, <strong>Vorname</strong>, <strong>E-Mail</strong> und <strong>Staatsangehörigkeit</strong> erfassen. Hinzu kommt eine Adresse aus <strong>PLZ/Ort</strong>, <strong>Ortsteil</strong>, <strong>Straße mit Hausnummer</strong>, <strong>Adresszusatz</strong> und <strong>Bemerkungen</strong>. Legen Sie außerdem fest, ob <strong>Anschreiben</strong> an diese Adresse versendet werden sollen.</p><p>Die zur Auswahl stehenden <em>Erzieherarten</em> werden über den entsprechenden <em>Katalog</em> eingestellt.</p><h2 id="telefonnummern" tabindex="-1">Telefonnummern <a class="header-anchor" href="#telefonnummern" aria-label="Permalink to &quot;Telefonnummern&quot;">​</a></h2><p>In dieser Auflistung können unabhängig von den obigen Erziehungsberechtigten Telefonnummern zu verschiedenen Ansprechpartnern erfasst werden.</p><p>Ein Eintrag umfasst dabei die Angaben <em>Ansprechpartner</em>, <em>Telefonnummer</em>, das Kennzeichen <strong>Für Weitergabe gesperrt</strong> und eine <em>Bemerkung</em>.</p><p>Die hier zur Verfügung stehenden <em>Telefonarten</em> werden ebenfalls über den entsprechenden <em>Katalog</em> eingestellt.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Gesperrte Telefonnummern werden in der Telefon-Datenquelle für Reports nicht berücksichtigt.")],-1),e("p",null,[n("Das Feld "),e("strong",null,"Für Weitergabe gesperrt"),n(" kann bearbeitet werden. Prüfen Sie bei Kontaktänderungen auch die zugehörige Weitergabeeinstellung.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Erz.-Berechtigte_/_Telefonnummern_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4690.")],-1)])])}const p=s(l,[["render",d]]);export{b as __pageData,p as default};
